mapper.update:
MERGE INTO M_PRODUCT t USING (
SELECT #{row.materialNumber, jdbcType=VARCHAR} AS name, #{row.executionStandard, jdbcType=VARCHAR} AS theme_name, #{row.ean13, jdbcType=VARCHAR} AS intscode, #{row.safetyCategory, jdbcType=VARCHAR} AS safety_category, #{row.fabCode, jdbcType=VARCHAR} AS fabcode, #{row.fabElement, jdbcType=VARCHAR} AS fabelement, #{row.acCode, jdbcType=VARCHAR} AS accode, #{row.accElement, jdbcType=VARCHAR} AS accelement FROM dual
) src ON (t.name = src.name) WHEN MATCHED THEN UPDATE SET t.THEME_NAME = CASE WHEN src.theme_name IS NOT NULL THEN src.theme_name ELSE t.THEME_NAME END, t.INTSCODE = CASE WHEN src.intscode IS NOT NULL THEN src.intscode ELSE t.INTSCODE END, t.SAFETY_CATEGORY = CASE WHEN src.safety_category IS NOT NULL THEN src.safety_category ELSE t.SAFETY_CATEGORY END, t.FABCODE = CASE WHEN src.fabcode IS NOT NULL THEN src.fabcode ELSE t.FABCODE END, t.FABELEMENT = CASE WHEN src.fabelement IS NOT NULL THEN src.fabelement ELSE t.FABELEMENT END, t.ACCODE = CASE WHEN src.accode IS NOT NULL THEN src.accode ELSE t.ACCODE END, t.ACCELEMENT = CASE WHEN src.accelement IS NOT NULL THEN src.accelement ELSE t.ACCELEMENT END

mapper.select:
SELECT * FROM (
    SELECT TMP.*, ROW_NUMBER() OVER (ORDER BY MATERIAL_NUMBER) AS RN FROM (
        SELECT product.ID           AS PRODUCT_ID,
               product.name         AS MATERIAL_NUMBER,
               product.VALUE        AS MATERIAL_NAME,
               product.STYLE_NO     AS STYLE_NUMBER,
               product.PRECOST      AS PRECOST
        FROM M_PRODUCT product

    ) TMP
) WHERE RN > #{offset} AND RN <= #{offset} + #{pageSize}

