MERGE INTO M_PRODUCT t USING (
SELECT #{row.materialNumber} AS name, NULLIF(TRIM(#{row.precost}), '') AS precost FROM dual
) src ON (t.name = src.name) WHEN MATCHED THEN UPDATE SET t.PRECOST = src.precost
